-- https://wiki.hypr.land/Configuring/Basics/Monitors/
-- monitor = name, resolution, position, scale, transform, 0
-- monitor = ,preferred,auto,auto,transform,0
-- monitor = ,preferred,auto,1,mirror, LVDS-1
-- monitor = LVDS-1, 1366x768@60, 0x0, 1, transform, 0
-- monitor = LVDS-1, disable
-- monitor = VGA-1, 1680x1050@60, 1366x0, 1, transform, 1
-- monitor = HDMI-A-1, 1680x1050@60, -1050x-912, 1, transform, 1
-- monitor = HDMI-A-1, 1680x1050@60, 1366x-912, 1, transform, 1
-- monitor = HDMI-A-1, disable

hl.monitor({
    output = "HDMI-A-2",
    mode = "1680x1050@60",
    -- mode = "1920x1080@60",
    position = "auto-center-right",
    scale = 1,
    transform = 1,
})

-- Plug-and-play any monitors not specified with an explicit rule
-- automatically preferred resolution and placed on the right of the other(s)
hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = 1,
})


-- https://wiki.hypr.land/Configuring/Basics/Autostart/
-- exec-once = pcmanfm -d
-- exec-once = swaybg --output LVDS-1 --mode fill --image /usr/share/backgrounds/fgm.png
-- exec-once = swaybg --output HDMI-A-1 --mode fit --color 000000 --image /usr/share/backgrounds/pluto-portrait-enhanced-color.png
hl.on("hyprland.start", function()
	-- hl.exec_cmd("pcmanfm -d")
    hl.exec_cmd("foot --server")
    hl.exec_cmd(bar)

	-- hl.exec_cmd("swaybg --output LVDS-1 --mode fill --image /usr/share/backgrounds/fgm.png")
	-- hl.exec_cmd("swaybg --output HDMI-A-1 --mode fit --color 000000 --image /usr/share/backgrounds/pluto-portrait-enhanced-color.png")
	hl.exec_cmd("swaybg --output eDP-1 --mode fill --image /usr/share/backgrounds/fgm.png")
	hl.exec_cmd("swaybg --output HDMI-A-2 --mode fit --color 000000 --image /usr/share/backgrounds/pluto-portrait-enhanced-color.png")

	-- https://wiki.archlinux.org/title/GNOME/Keyring#Using_gnome-keyring-daemon_outside_desktop_environments_(KDE,_GNOME,_XFCE,_...)
    hl.exec_cmd("dbus-update-activation-environment DISPLAY XAUTHORITY WAYLAND_DISPLAY")
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets")

end)


