-- Media/Volume/Brightness Control
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("mpc toggle"))
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("mpc pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("mpc next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("mpc cdprev"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("volfade-rs toggle-mute"))
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("volfade-rs increase 11"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("volfade-rs decrease 7"))
hl.bind("SHIFT + XF86AudioRaiseVolume", hl.dsp.exec_cmd("volfade-rs inc 1"))
hl.bind("SHIFT + XF86AudioLowerVolume", hl.dsp.exec_cmd("volfade-rs dec 1"))
hl.bind(mod .. " + F3", hl.dsp.exec_cmd("pavucontrol --tab=3"))
hl.bind(mod .. " + F2", hl.dsp.exec_cmd(terminal .. " --title 'Volume Control' -- wiremix"))
hl.bind(mod .. " + XF86AudioRaiseVolume", hl.dsp.exec_cmd("pavucontrol --tab=3"))
hl.bind(mod .. " + XF86AudioLowerVolume", hl.dsp.exec_cmd(terminal .. " --title 'Volume Control' -- wiremix"))
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("xbacklight -inc 3 -fps 60 -time 111 -perceived"), { repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("xbacklight -dec 3 -fps 60 -time 111 -perceived"), { repeating = true })
hl.bind("SHIFT + XF86MonBrightnessUp", function()
    hl.config({ decoration = { screen_shader = "" } })
end)
hl.bind("SHIFT + XF86MonBrightnessDown", function()
    hl.config({ decoration = { screen_shader = "~/.config/hypr/blue-light-filter.frag" } })
end)
hl.bind(mod .. " + XF86MonBrightnessUp", hl.dsp.dpms({ action = "on" }))
hl.bind(mod .. " + XF86MonBrightnessDown", function()
    hl.exec_cmd("sleep 1")
    hl.dispatch(hl.dsp.dpms({ action = "off" }))
end)
hl.bind(mod .. " + F7", function()
    hl.exec_cmd("sleep 1")
    hl.dispatch(hl.dsp.dpms({ action = "toggle" }))
end)
hl.bind(mod .. " + Menu", hl.dsp.exec_cmd("kblight"))

