-- https://wiki.hypr.land/Configuring/Basics/Window-Rules/#rules
-- https://wiki.hypr.land/Configuring/Basics/Window-Rules/#layer-rules
-- https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/#workspace-rules

-- Global Rules
hl.window_rule({
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.workspace_rule({
    workspace = "special:magic",
    on_created_empty = floatingTerminal,
})

-- Monitor Rules
hl.workspace_rule({
    workspace = "m[HDMI-A-1]",
    gaps_in = 8,
    gaps_out = 16,
    border_size = 1,
})

-- workspace = 1, monitor:HDMI-A-1, default:true
-- workspace = 2, monitor:HDMI-A-1
-- workspace = 3, monitor:HDMI-A-1
-- workspace = 4, monitor:HDMI-A-1
-- workspace = 5, monitor:HDMI-A-1
-- workspace = 6, monitor:LVDS-1
-- workspace = 7, monitor:LVDS-1
-- workspace = 8, monitor:LVDS-1
-- workspace = 9, monitor:LVDS-1
-- workspace = 10, monitor:LVDS-1, default:true
-- workspace = 1, monitor:LVDS-1, default:true
-- workspace = 2, monitor:LVDS-1
-- workspace = 3, monitor:LVDS-1
-- workspace = 4, monitor:LVDS-1
-- workspace = 5, monitor:LVDS-1
-- workspace = 6, monitor:HDMI-A-1
-- workspace = 7, monitor:HDMI-A-1
-- workspace = 8, monitor:HDMI-A-1
-- workspace = 9, monitor:HDMI-A-1
-- workspace = 10, monitor:HDMI-A-1, default:true
-- Workspaces 1-5 → eDP-1 (1 is default)
for i = 1, 5 do
    hl.workspace_rule({ workspace = tostring(i), monitor = "eDP-1", default = (i == 1) })
end
-- Workspaces 6-10 → HDMI-A-2 (10 is default)
for i = 6, 10 do
    hl.workspace_rule({ workspace = tostring(i), monitor = "HDMI-A-2", default = (i == 10) })
end

-- firefoxd
hl.workspace_rule({
